function getAverageBrightness(pngBuffer: Buffer): number {
  const png = PNG.sync.read(pngBuffer);
  let totalBrightness = 0;
  const pixelCount = png.width * png.height;

  for (let y = 0; y < png.height; y++) {
    for (let x = 0; x < png.width; x++) {
