  const browser = await chromium.launch();
  const context = await browser.newContext();
  const page = await context.newPage();
  const client = await page.context().newCDPSession(page);
  await client.send('Performance.enable');

  // Block picsum to avoid networkidle stalls
  await page.route('**/picsum.photos/**', (route) =>
    route.fulfill({
      status: 200,
      contentType: 'image/svg+xml',
      body: '<svg xmlns="http://www.w3.org/2000/svg" width="400" height="300"><rect width="100%" height="100%" fill="#ccc"/></svg>',
    })
  );

  await page.goto(url, { waitUntil: 'domcontentloaded' });

  // Let content shifts settle (Late banner is 2500ms)
  await page.waitForTimeout(4000);
  await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));
  await page.waitForTimeout(1500);
  await page.evaluate(() => window.scrollTo(0, 0));
  await page.waitForTimeout(1500);

  const perfMetrics = await client.send('Performance.getMetrics');
  const metrics: Record<string, number> = {};
  for (const m of perfMetrics.metrics) metrics[m.name] = m.value;

  const cls = metrics['CumulativeLayoutShift'] || 0;
  await browser.close();

  console.log(JSON.stringify({ url, cls: Math.round(cls * 1000) / 1000, layoutCount: metrics['LayoutCount'] }, null, 2));
}

measureCLS(process.argv[2] || 'http://localhost:3000').catch((e) => {
  console.error(e);
  process.exit(1);
});
