  );

  await page.goto(url, { waitUntil: 'commit' });
  await page.waitForTimeout(80);
  const earlyBg = await page.evaluate(() => getComputedStyle(document.body).backgroundColor);
  const earlyHtmlTheme = await page.evaluate(() => document.documentElement.getAttribute('data-theme'));
  await page.waitForTimeout(3000);
  const finalBg = await page.evaluate(() => getComputedStyle(document.body).backgroundColor);
  const finalHtmlTheme = await page.evaluate(() => document.documentElement.getAttribute('data-theme'));
  await browser.close();
  console.log(JSON.stringify({ earlyBg, earlyHtmlTheme, finalBg, finalHtmlTheme, flicker: earlyBg !== finalBg }, null, 2));
}

